/* KV CELL OS PREMIUM V10 ULTIMATE FINAL */
function toast(s,type='info'){
  let t=document.getElementById('toast');
  if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}
  t.textContent=s||''; t.classList.add('show'); clearTimeout(t._timer); t._timer=setTimeout(()=>t.classList.remove('show'),3200);
}
async function aiSafe(data){
  try{return await api('/api/ai/chat',{method:'POST',body:JSON.stringify(data)})}
  catch(e){return {ok:false,reply:e.message||'Não foi possível falar com a IA agora.'}}
}
function botTag(){return '<span class="badge bot">BOT</span>'}
function unitTag(u){return `<span class="badge ${u==='LAGOS'?'y':'p'}">${esc(u||'TODOS')}</span>`}
function logTag(){return '<span class="badge log">LOG</span>'}

pages.chat=async()=>{
  let [msgs,logs,ai,summary]=await Promise.all([api('/api/chat?unit=TODOS'),api('/api/activity?unit=TODOS'),api('/api/ai/status'),api('/api/dashboard?unit='+encodeURIComponent(UNIT))]);
  const all=[];
  msgs.forEach(x=>all.push({kind:'msg',date:x.created_at,user:x.user_name,text:x.message,unit:x.unit,tag:x.user_name==='KV CELL BOT [I.A]'?'BOT':x.user_name==='CLIENTE'?'LOG':x.unit}));
  logs.forEach(x=>all.push({kind:'log',date:x.created_at,user:x.user_name,text:x.action,unit:x.unit,tag:'LOG',details:x.details}));
  all.sort((a,b)=>String(a.date).localeCompare(String(b.date)));
  $('#content').innerHTML=head('KV CELL BOT [I.A] • Central','Tudo em um só lugar: IA, LAGOS, MAGÉ e LOG de toda a operação',`<button class="btn ghost" onclick="loadChat()">↻ Atualizar</button><span class="badge ${ai.configured?'g':'r'}">IA ${ai.configured?'ONLINE':'SEM CHAVE'}</span>`)+
  `<div class="cards bot-kpis"><div class="metric"><div class="label">GANHOS</div><div class="value green">${money(summary.income)}</div></div><div class="metric"><div class="label">DESPESAS</div><div class="value red">${money(summary.expense)}</div></div><div class="metric"><div class="label">RESULTADO</div><div class="value yellow">${money(summary.income-summary.expense)}</div></div></div><div class="bot-layout"><section class="panel bot-panel"><div class="bot-head"><div class="bot-avatar">KV</div><div><h2>KV CELL BOT <span>[I.A]</span></h2><p>Precificação • orçamento • textos • dúvidas • operação</p></div></div><div id="botMessages" class="bot-messages"><div class="bot-msg ai"><div>${botTag()} ${unitTag('TODOS')}</div><div>Olá! Pode perguntar quanto cobrar, pedir um texto de orçamento, calcular margem, criar mensagem para cliente ou tirar dúvidas da plataforma. Eu não altero seus dados sozinho.</div></div>${all.slice(-60).map(x=>`<div class="bot-msg ${x.tag==='BOT'?'ai':'event'}"><div>${x.tag==='LOG'?logTag():x.tag==='BOT'?botTag():unitTag(x.unit)} <b>${esc(x.user||'')}</b></div><div>${esc(x.text||'')}</div>${x.details?`<small>${esc(x.details)}</small>`:''}<small>${esc(x.date||'')}</small></div>`).join('')}</div><form id="botForm" class="bot-input"><textarea name="message" class="textarea" rows="2" placeholder="Ex.: Quanto devo cobrar para trocar a tela de um A15? / Faça um orçamento bonito para WhatsApp..." required></textarea><button class="btn" type="submit">Enviar ↗</button></form></section><aside class="panel"><h3>⚡ Ações rápidas</h3><div class="quick"><button onclick="botQuick('Me ajude a precificar um serviço. Faça perguntas sobre custo, modelo e margem.')">💰 Precificar serviço</button><button onclick="botQuick('Crie um texto de orçamento profissional para WhatsApp.')">🧾 Criar orçamento</button><button onclick="botQuick('Me ajude a calcular lucro de uma venda de aparelho.')">📱 Calcular lucro</button><button onclick="botQuick('Como posso cadastrar uma compatibilidade de película com segurança?')">🛡️ Películas</button></div><hr><h3>Legenda</h3><p>${botTag()} Resposta da IA</p><p>${unitTag('LAGOS')} Unidade Lagos</p><p>${unitTag('MAGÉ')} Unidade Magé</p><p>${logTag()} Ação do sistema</p></aside></div>`;
  $('#botForm').onsubmit=async e=>{e.preventDefault();const d=formValues(e.target);d.history=all.slice(-8).map(x=>({role:x.tag==='BOT'?'assistant':'user',message:x.text}));e.target.reset();const r=await aiSafe(d);const box=$('#botMessages');box.insertAdjacentHTML('beforeend',`<div class="bot-msg user"><div>${unitTag(UNIT)} <b>${esc(ME?.name||'Você')}</b></div><div>${esc(d.message)}</div></div><div class="bot-msg ai"><div>${botTag()}</div><div>${esc(r.reply||'')}</div></div>`);box.scrollTop=box.scrollHeight};
  const bm=$('#botMessages');bm.scrollTop=bm.scrollHeight;
};
function botQuick(x){const ta=document.querySelector('#botForm textarea');if(ta){ta.value=x;ta.focus()}}
function loadChat(){render()}

