/* ================= KV CELL V20 ULTIMATE ================= */
function statusOptions(kind){
  return kind==='unlock'
    ? ['aberto','em andamento','aguardando dados','pronto','entregue','pendente','cancelado','garantia']
    : ['aberto','aguardando peça','em andamento','pronto','entregue','cancelado','garantia','garantia em análise','garantia em reparo'];
}
function waText(status, os, customer){
  const name=customer?.name||'cliente';
  const map={
    'aberto':`Olá ${name}! 👋 Sua OS #${os.id} foi recebida pela KV CELL e está aguardando atendimento.`,
    'aguardando peça':`Olá ${name}! 📦 Sua OS #${os.id} está aguardando a chegada da peça/material necessário.`,
    'em andamento':`Olá ${name}! 🔧 Sua OS #${os.id} está em andamento na bancada da KV CELL.`,
    'pronto':`Olá ${name}! ✅ Sua OS #${os.id} está pronta para retirada na KV CELL.`,
    'entregue':`Olá ${name}! 📱 A OS #${os.id} foi finalizada/entregue. Obrigado por escolher a KV CELL!`,
    'cancelado':`Olá ${name}. A OS #${os.id} foi cancelada. Entre em contato com a KV CELL para mais informações.`,
    'garantia':`Olá ${name}! 🛡️ O aparelho retornou em garantia e a KV CELL já registrou o atendimento vinculado à OS #${os.id}.`,
    'garantia em análise':`Olá ${name}! 🛡️ Sua garantia da OS #${os.id} está em análise pela equipe técnica.`,
    'garantia em reparo':`Olá ${name}! 🔧 O atendimento de garantia da OS #${os.id} está em reparo.`
  };
  return map[status]||`Olá ${name}! Sua OS #${os.id} teve o status atualizado para: ${status}.`;
}
async function serviceCustomer(id){
  try{return (await api('/api/customers?unit=TODOS')).find(x=>x.id===Number(id))||{}}catch{return {}}
}
async function statusService(id,status){
  try{await api('/api/services',{method:'PUT',body:JSON.stringify({id,status})});toast('Status da OS atualizado');render()}catch(e){toast(e.message,'error')}
}
async function statusUnlock(id,status){
  try{await api('/api/unlocks',{method:'PUT',body:JSON.stringify({id,status})});toast('Status do desbloqueio atualizado');render()}catch(e){toast(e.message,'error')}
}
async function whatsappService(id,status){
  const d=(await api('/api/services?unit=TODOS')).find(x=>x.id===id); if(!d)return;
  const c=await serviceCustomer(d.customer_id); const phone=String(c.phone||'').replace(/\D/g,'');
  if(!phone){toast('Cliente sem telefone cadastrado','error');return}
  const track=location.origin+'/public/os/'+d.public_token;
  const msg=waText(status||d.status,d,c)+`\n\n🔗 Acompanhe sua OS em tempo real:\n${track}`;
  window.open('https://wa.me/'+(phone.startsWith('55')?phone:'55'+phone)+'?text='+encodeURIComponent(msg),'_blank');
}
async function whatsappUnlock(id,status){
  const d=(await api('/api/unlocks?unit=TODOS')).find(x=>x.id===id); if(!d)return;
  const c=await serviceCustomer(d.customer_id); const phone=String(c.phone||'').replace(/\D/g,'');
  if(!phone){toast('Cliente sem telefone cadastrado','error');return}
  const track=location.origin+'/public/unlock/'+d.public_token;
  const msg=waText(status||d.status,{id:d.id},c)+`\n\n🔗 Acompanhe o serviço:\n${track}`;
  window.open('https://wa.me/'+(phone.startsWith('55')?phone:'55'+phone)+'?text='+encodeURIComponent(msg),'_blank');
}
