// Chat: /bot é obrigatório e BOT/LOG não são botões.
pages.chat=async()=>{
 const [msgs,logs,ai,summary]=await Promise.all([api('/api/chat?unit=TODOS'),api('/api/activity?unit=TODOS'),api('/api/ai/status'),api('/api/dashboard?unit='+encodeURIComponent(UNIT))]);
 const all=[]; msgs.forEach(x=>all.push({date:x.created_at,user:x.user_name,text:x.message,unit:x.unit,tag:x.user_name==='KV CELL BOT [I.A]'?'BOT':x.user_name==='CLIENTE'?'LOG':x.unit})); logs.forEach(x=>all.push({date:x.created_at,user:x.user_name,text:x.action,unit:x.unit,tag:x.tag==='BOT'?'BOT':'LOG',details:x.details})); all.sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 $('#content').innerHTML=head('Chat KV CELL','Chat interno entre LAGOS e MAGÉ • IA somente com /bot',`<button class="btn ghost" onclick="render()">↻ Atualizar</button><span class="badge ${ai.configured?'g':'r'}">IA ${ai.configured?'ONLINE':'SEM CHAVE'}</span>`)+`<div class="cards"><div class="metric"><div class="label">GANHOS</div><div class="value green">${money(summary.income)}</div></div><div class="metric"><div class="label">DESPESAS</div><div class="value red">${money(summary.expense)}</div></div><div class="metric"><div class="label">RESULTADO</div><div class="value yellow">${money(summary.income-summary.expense)}</div></div></div><section class="panel bot-panel"><div id="botMessages" class="bot-messages">${all.slice(-80).map(x=>`<div class="bot-msg ${x.tag==='BOT'?'ai':'event'}"><div>${x.tag==='BOT'?botTag():logTag()} ${unitTag(x.unit)} <b>${esc(x.user||'')}</b></div><div>${esc(x.text||'')}</div>${x.details?`<small>${esc(x.details)}</small>`:''}<small>${esc(x.date||'')}</small></div>`).join('')||'<p class="muted">Nenhuma mensagem ainda.</p>'}</div><form id="botForm" class="bot-input"><textarea name="message" class="textarea" rows="2" placeholder="Mensagem normal ou /bot sua pergunta para a IA" required></textarea><button class="btn" type="submit">Enviar ↗</button></form><p class="muted">Mensagem normal = chat. Para IA, comece com <b>/bot</b>. A IA não lê automaticamente o chat.</p></section>`;
 $('#botForm').onsubmit=async e=>{e.preventDefault();const d=formValues(e.target);e.target.reset();try{let r;if(/^\s*\/bot(?:\s|$)/i.test(d.message)){r=await aiSafe({message:d.message});}else{r=await api('/api/chat',{method:'POST',body:JSON.stringify({unit:UNIT,message:d.message})});r.reply='Mensagem enviada';}await render();toast(r.reply||'Enviado')}catch(x){toast(x.message,'error')}};
 const bm=$('#botMessages');if(bm)bm.scrollTop=bm.scrollHeight;
};

