window.guaranteeForm=function(){formModal('Nova Garantia',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'])}${customerPicker('customer_id','Cliente')}${f('source_type','Origem','select',['service','unlock','manual'])}${f('source_id','ID da OS','number','')}${f('device','Aparelho')}${f('description','Serviço / motivo','textarea','',true)}${f('start_date','Início','date')}${f('end_date','Fim','date')}${f('status','Status','select',['ativa','em análise','em reparo','encerrada'])}${f('notes','Observações','textarea','',true)}</div>`,async()=>{const m=$('#modal'),d=formValues(m.querySelector('#modalForm'));await api('/api/guarantees',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Garantia cadastrada');render()});setTimeout(wirePickers,40)};

pages.fiado=async()=>{const d=await api('/api/fiado?unit='+encodeURIComponent(UNIT));const open=d.filter(x=>x.status!=='pago').reduce((a,x)=>a+Number(x.balance||0),0), late=d.filter(x=>x.status==='atrasado').length;$('#content').innerHTML=head('Controle de Fiado','Contas a receber integradas às OS, desbloqueios e vendas',`<button class="btn" onclick="fiadoForm()">＋ Novo Fiado</button>`)+`<div class="cards"><div class="metric"><div class="label">A RECEBER</div><div class="value yellow">${money(open)}</div></div><div class="metric"><div class="label">ATRASADOS</div><div class="value red">${late}</div></div><div class="metric"><div class="label">CONTAS</div><div class="value">${d.length}</div></div><div class="metric"><div class="label">UNIDADE</div><div class="value">${UNIT}</div></div></div>`+table(d,[['customer_name','Cliente'],['description','Origem / Descrição'],['total','Total',r=>money(r.total)],['down_payment','Entrada',r=>money(r.down_payment)],['balance','Saldo',r=>money(r.balance)],['due_date','Vencimento'],['status','Status',r=>badge(r.status)]],r=>`<button class="btn ghost" onclick="receiveFiado(${r.id},${r.balance})">💰 Receber</button> <button class="btn ghost" onclick="fiadoWhats(${r.id})">🟢 WhatsApp</button>`) };
