// V100 photo policy: 3 images by default, resized client-side to save database space.
photoBox=function(){return `<div class="field full"><label>Fotos do Aparelho <span class="photo-counter" id="photoCounter">0 de 3 fotos</span></label><div class="drop">📷 Imagens são otimizadas automaticamente até 800px para economizar espaço.<input id="photos" type="file" accept="image/*" multiple></div><div id="preview" class="photos" style="margin-top:9px"></div><small class="muted">Plano padrão: até 3 fotos por OS.</small></div>`};
readPhotos=async function(){const input=$('#photos');const files=[...(input?.files||[])].slice(0,3);const arr=[];for(const file of files){const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const resized=await new Promise(resolve=>{const im=new Image();im.onload=()=>{const max=800,scale=Math.min(1,max/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',0.82))};im.onerror=()=>resolve(data);im.src=data});arr.push(resized)}return arr};
function wirePhotoLimit(){const input=$('#photos'),counter=$('#photoCounter');if(!input)return;input.onchange=()=>{if(input.files.length>3){toast('Limite de 3 fotos por OS.');const dt=new DataTransfer();[...input.files].slice(0,3).forEach(f=>dt.items.add(f));input.files=dt.files}if(counter)counter.textContent=`${input.files.length} de 3 fotos`};}
function entryChecklist(){return `<div class="checklist-toolbar"><button type="button" class="mini" onclick="checkAllEntry(true)">☷ Checklist Automático</button><button type="button" class="mini" onclick="checkAllEntry(false)">⊘ Impossibilitado de teste</button></div>${checklist()}`}
window.checkAllEntry=function(mode){$$('#modalForm input[name="checklist"]').forEach(x=>x.checked=mode);toast(mode?'Checklist preenchido automaticamente.':'Testes marcados como impossibilitados; revise antes de salvar.')}
/* KV CELL V101 SUPREME — visual refinement + reference-style analytics */
function miniBarChart(items, valueKey, labelKey, formatter){
  const max=Math.max(1,...items.map(x=>Number(x[valueKey]||0)));
  return `<div class="vchart-bars">${items.map(x=>`<div class="vbar-item"><div class="vbar-value">${formatter?formatter(x[valueKey]):Number(x[valueKey]||0)}</div><div class="vbar-track"><i style="height:${Math.max(4,(Number(x[valueKey]||0)/max)*150)}px"></i></div><small>${esc(x[labelKey]||'—')}</small></div>`).join('')}</div>`;
}
function donutChart(parts){
  const total=parts.reduce((a,x)=>a+Number(x.value||0),0)||1; let acc=0;
  const stops=parts.map(x=>{const a=acc/total*360;acc+=Number(x.value||0);const b=acc/total*360;return `${x.color} ${a}deg ${b}deg`}).join(',');
  return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${stops})"><div class="donut-hole"><b>${parts.reduce((a,x)=>a+Number(x.value||0),0)}</b><small>Total</small></div></div><div class="donut-legend">${parts.map(x=>`<span><i style="background:${x.color}"></i>${esc(x.label)} <b>${x.value}</b></span>`).join('')}</div></div>`;
}
function analyticsHeader(title,subtitle,buttons=''){return head(title,subtitle,buttons)}

// Registered technicians are selected by record, while the human-readable name is kept on the OS for backward compatibility.
function technicianPicker(name='technician_id',label='Técnico Responsável'){
 return `<div class="field"><label>${label}</label><select class="select tech-picker" name="${name}" data-tech-picker><option value="">Selecione um técnico cadastrado</option></select><small class="muted tech-picker-hint">O técnico selecionado recebe automaticamente os serviços e indicadores desta OS.</small></div>`;
}
async function wireTechnicianPickers(){
 const selects=$$('[data-tech-picker]'); if(!selects.length)return;
 try{
  const data=await api('/api/technicians?unit='+encodeURIComponent(UNIT));
  selects.forEach(sel=>{const current=sel.dataset.current||sel.value; sel.innerHTML='<option value="">Selecione um técnico cadastrado</option>'+data.filter(t=>t.active!==0).map(t=>`<option value="${t.id}">${esc(t.name)} · ${esc(t.unit||'TODOS')}</option>`).join(''); if(current)sel.value=String(current)});
 }catch(e){selects.forEach(sel=>sel.innerHTML='<option value="">Não foi possível carregar técnicos</option>')}
}
function selectedTechData(form){const sel=form?.querySelector('[data-tech-picker]');if(!sel)return {id:null,name:''};const opt=sel.options[sel.selectedIndex];return {id:sel.value?Number(sel.value):null,name:opt?.textContent?.split(' · ')[0]||''}}

