 const statusParts=[{label:'Pago',value:d.filter(x=>x.status==='pago').length,color:'#34d399'},{label:'Em aberto',value:d.filter(x=>x.status==='aberto').length,color:'#ffd400'},{label:'Vencido',value:d.filter(x=>x.status==='atrasado').length,color:'#ff5c68'}];
 const months={};d.forEach(x=>{const k=(x.due_date||x.created_at||'').slice(0,7)||'Sem data';months[k]=(months[k]||0)+Number(x.total||0)});const monthly=Object.entries(months).sort().slice(-8).map(([label,value])=>({label:label.slice(5)||label,value}));
