function fiadoTable(d){return table(d,[['id','#'],['customer_name','Cliente'],['description','Obra / Serviço'],['total','Total',r=>money(r.total)],['down_payment','Entrada',r=>money(r.down_payment)],['installments','Parcelas',r=>`${r.installments||1}x ${money(r.installment_value||0)}`],['balance','Saldo',r=>money(r.balance)],['due_date','Vencimento'],['status','Status',r=>badge(r.status)]],r=>`<button class="btn ghost" onclick="fiadoDetails(${r.id})">Detalhes</button> <button class="btn ghost" onclick="receiveFiado(${r.id},${r.balance})">💰 Receber</button> <button class="btn ghost" onclick="fiadoWhats(${r.id})">🟢 WhatsApp</button>`) }
