// Customer selector: never expose internal database IDs in the visible UI.
window.customerPickerV500=function(name='customer_id',label='Selecionar Cliente'){
  return `<div class="field full cp-wrap"><label>${esc(label)} <span class="muted">Digite o início do nome ou telefone</span></label><input class="input cp-input" data-cp-name="${name}" placeholder="Ex.: João ou 2299" autocomplete="off"><input type="hidden" name="${name}" value=""><div class="cp-results"></div></div>`;
};
window.wirePickersV500=function(){
  $$('.cp-input').forEach(inp=>{
    if(inp.dataset.v500==='1') return; inp.dataset.v500='1';
    const box=inp.closest('.cp-wrap'), hidden=box.querySelector('input[type=hidden]'), res=box.querySelector('.cp-results');
    inp.oninput=async()=>{
      const q=inp.value.trim(); hidden.value='';
      const form=box.closest('#modalForm');
      if(form) ['customer_name','customer_phone','customer_document'].forEach(n=>{const el=form.querySelector(`[name="${n}"]`);if(el)el.value=''});
      if(q.length<2){res.innerHTML='';return;}
      try{
        const data=await api('/api/customer-search?q='+encodeURIComponent(q));
        res.innerHTML=data.map(c=>`<button type="button" class="cp-option" data-id="${c.id}"><b>${esc(c.name)}</b><span>${esc(c.phone||'Sem telefone')} · ${c.service_count||0} atendimentos · Score ${c.score||0}</span></button>`).join('')||'<div class="cp-empty">Nenhum cliente encontrado.</div>';
        res.querySelectorAll('.cp-option').forEach(b=>b.onclick=()=>{
          const c=data.find(x=>String(x.id)===b.dataset.id); if(!c)return;
          hidden.value=c.id; inp.value=c.name+(c.phone?' · '+c.phone:'');
          res.innerHTML=`<div class="cp-selected"><b>${esc(c.name)}</b><span>${esc(c.document||'Documento não informado')} · ${esc(c.phone||'Sem telefone')}</span></div>`;
          if(form){const n=form.querySelector('[name="customer_name"]'),p=form.querySelector('[name="customer_phone"]'),doc=form.querySelector('[name="customer_document"]');if(n)n.value=c.name||'';if(p)p.value=c.phone||'';if(doc)doc.value=c.document||'';}
        });
      }catch(e){res.innerHTML=`<div class="cp-empty">${esc(e.message)}</div>`}
    };
  });
};

// Real edit helper used across the registries. Internal IDs are used only by the API,
