// Technical OS: preserve V300 form and add the exact requested device-password UI.
const _serviceFormV300=serviceForm;
serviceForm=function(seed={}){
  formModal('Nova Ordem de Serviço Técnica',`<div class="formgrid">
    ${f('unit','Unidade','select',['LAGOS','MAGÉ'],seed.unit||UNIT)}${customerPickerV500('customer_id','Selecionar Cliente')}${detailedClientFields()}
    ${f('brand','Marca', 'text',seed.brand||'')}${f('model','Modelo *','text',seed.model||'')}${f('imei','IMEI','text',seed.imei||'')}${f('serial','Número de série','text',seed.serial||'')}${f('device_id','Aparelho vinculado','hidden',seed.device_id||'')}
    ${lockCredentialFieldsV500()}
    ${f('description','Problema relatado / Serviço solicitado','textarea',seed.description||'',true)}${f('diagnosis','Diagnóstico técnico','textarea','',true)}
    ${f('price','Valor do serviço','number','0')}${f('cost_material','Custo de peças','number','0')}${f('cost_labor','Custo de mão de obra','number','0')}${f('cost_extra','Outros custos / deslocamento','number','0')}
    ${f('warranty','Garantia','text','90 dias')}${f('technician','Técnico / operador')}${f('status','Status','select',['aberto','aguardando peça','em andamento','pronto','finalizado','entregue','cancelado'])}
    <div class="field full"><label>Checklist técnico</label>${checklist()}</div>${photoBox()}${f('notes','Observações','textarea','',true)}
  </div>`,async()=>{
    const m=$('#modal'),d=formValues(m.querySelector('#modalForm'));d.checklist=collectChecks(m);d.photos=await readPhotos();
    if(seed.customer_id&&!d.customer_id)d.customer_id=seed.customer_id;
    if(!d.customer_id)return toast('Selecione o cliente.','error');
    d.details={...(seed.details||{}),customer_name:d.customer_name,customer_phone:d.customer_phone,customer_document:d.customer_document,brand:d.brand,model:d.model,imei:d.imei,serial:d.serial,pin:d.pin||'',pattern:d.pattern||'',lock_type:d.lock_type||''};
    try{await api('/api/services',{method:'POST',body:JSON.stringify(d)});closeModal();toast('OS criada com vínculo completo');render()}catch(e){toast(e.message,'error')}
  });
  setTimeout(()=>{wirePickersV500();if(seed.customer_id)preselectCustomerV500(seed.customer_id)},50);
};
function lockCredentialFieldsV500(){return `<div class="field full lock-mode-wrap"><label>Senha do aparelho <span class="muted">opcional</span></label><div class="lock-mode-tabs"><button type="button" class="lock-tab active" onclick="setLockModeV500('pattern',this)">🔘 Desenho</button><button type="button" class="lock-tab" onclick="setLockModeV500('pin',this)">🔢 PIN</button></div><input type="hidden" name="lock_type" value="pattern"><input type="hidden" name="pattern" value=""><input type="hidden" name="pin" value=""><div id="patternBoxV500" class="pattern-box"><div class="pattern-grid">${Array.from({length:9},(_,i)=>`<button type="button" class="pattern-dot" data-i="${i}" onpointerdown="patternStartV500(event,${i})" onpointerenter="patternEnterV500(${i})"></button>`).join('')}</div><div id="patternReadoutV500" class="pattern-readout">Deslize ligando as bolinhas na ordem da senha.</div><button type="button" class="mini" onclick="clearPatternV500()">Limpar desenho</button></div><div id="pinBoxV500" class="pin-box" hidden><input class="input" name="pin_visible" inputmode="numeric" maxlength="6" minlength="4" placeholder="PIN de 4 a 6 dígitos" oninput="syncPinV500(this)"></div></div>`}
let _p500=false,_seq500=[];
window.setLockModeV500=(mode,btn)=>{const m=$('#modalForm');if(!m)return;m.querySelector('[name=lock_type]').value=mode;m.querySelectorAll('.lock-tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('#patternBoxV500').hidden=mode!=='pattern';$('#pinBoxV500').hidden=mode!=='pin';if(mode==='pin')clearPatternV500()};
window.patternStartV500=(e,i)=>{e.preventDefault();_p500=true;_seq500=[];clearPatternV500();patternEnterV500(i);window.addEventListener('pointerup',()=>{_p500=false},{once:true})};
window.patternEnterV500=i=>{if(!_p500||_seq500.includes(i))return;_seq500.push(i);const b=$(`#patternBoxV500 .pattern-dot[data-i="${i}"]`);if(b)b.classList.add('selected');const m=$('#modalForm');if(m){m.querySelector('[name=pattern]').value=_seq500.join('-');$('#patternReadoutV500').textContent='Ordem: '+_seq500.map(x=>x+1).join(' → ')}};
window.clearPatternV500=()=>{_p500=false;_seq500=[];$$('#patternBoxV500 .pattern-dot').forEach(x=>x.classList.remove('selected'));const m=$('#modalForm');if(m){m.querySelector('[name=pattern]').value='';const o=$('#patternReadoutV500');if(o)o.textContent='Deslize ligando as bolinhas na ordem da senha.'}};
window.syncPinV500=el=>{el.value=String(el.value||'').replace(/\D/g,'').slice(0,6);const m=$('#modalForm');if(m)m.querySelector('[name=pin]').value=el.value};
async function preselectCustomerV500(id){try{const c=(await api('/api/customers?unit=TODOS')).find(x=>x.id===Number(id));if(!c)return;const m=$('#modalForm'),h=m.querySelector('[name=customer_id]'),i=m.querySelector('.cp-input');if(h)h.value=c.id;if(i)i.value=c.name+(c.phone?' · '+c.phone:'');['customer_name','customer_phone','customer_document'].forEach(n=>{const e=m.querySelector(`[name="${n}"]`);if(e)e.value=n==='customer_name'?c.name:n==='customer_phone'?c.phone||'':c.document||''})}catch{}}

// Unlock OS stays intentionally simple: no checklist, no photos, no warranty.
unlockForm=function(seed={}){formModal('Novo Desbloqueio',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'],seed.unit||UNIT)}${customerPickerV500('customer_id','Selecionar Cliente')}${detailedClientFields()}${f('brand','Marca', 'text',seed.brand||'')}${f('model','Modelo','text',seed.model||'')}${f('imei','IMEI','text',seed.imei||'')}${f('serial','Número de série','text',seed.serial||'')}${f('operator_original','Operadora original')}${f('kind','Tipo de desbloqueio','select',['FRP / Conta Google','MDM','Desbloqueio de rede','Software','Remoção de PayJoy','Outro'])}${f('provider','Servidor / Provedor')}${f('anydesk','AnyDesk / suporte remoto')}${f('technician','Técnico responsável')}${f('description','Descrição do serviço','textarea','',true)}${f('account_email','E-mail da conta','email')}${f('account_password','Senha da conta','password')}${f('pin','PIN')}${f('pattern','Desenho / padrão')}${f('expected_date','Prazo','date')}${f('estimated_time','Tempo estimado')}${f('priority','Prioridade','select',['Normal','Alta','Urgente'])}${f('price','Valor do serviço','number','0')}${f('entry_value','Entrada','number','0')}${f('cost_material','Custo material/ferramenta','number','0')}${f('cost_labor','Custo de mão de obra','number','0')}${f('cost_extra','Outros custos','number','0')}${f('notes','Observações','textarea','',true)}<div class="field full guarantee-alert"><b>⚠ SEM GARANTIA</b><span>Desbloqueios são executados sem garantia.</span></div></div>`,async()=>{const m=$('#modal'),d=formValues(m.querySelector('#modalForm'));d.status='aberto';d.warranty='0 dias';d.checklist={};d.photos=[];d.details={...d,customer_name:d.customer_name,customer_phone:d.customer_phone,customer_document:d.customer_document};if(seed.customer_id&&!d.customer_id)d.customer_id=seed.customer_id;if(!d.customer_id)return toast('Selecione o cliente.','error');try{await api('/api/unlocks',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Desbloqueio criado sem checklist/fotos/garantia');render()}catch(e){toast(e.message,'error')}});setTimeout(()=>{wirePickersV500();if(seed.customer_id)preselectCustomerV500(seed.customer_id)},50)};

// OS actions: status -> finalizado -> WhatsApp; entrega -> white checklist -> ENTREGUE + Financeiro.
window.finalizeServiceV500=async function(id){const d=(await api('/api/services?unit=TODOS')).find(x=>x.id===id);if(!d)return;await api('/api/services',{method:'PUT',body:JSON.stringify({id,status:'finalizado'})});toast('Serviço finalizado');try{const c=await serviceCustomer(d.customer_id);const phone=String(c.phone||'').replace(/\D/g,'');if(phone)window.open('https://wa.me/'+(phone.startsWith('55')?phone:'55'+phone)+'?text='+encodeURIComponent(`Olá ${c.name||'cliente'}! 📱 Seu aparelho da OS está pronto na KV CELL. Acompanhe pelo link: ${location.origin}/public/os/${d.public_token}`),'_blank')}catch{}render()};
window.deliverServiceV500=async function(id){const d=(await api('/api/services?unit=TODOS')).find(x=>x.id===id);if(!d)return;formModal('Checklist de Saída · Serviço Entregue',`<div class="delivery-white-card"><div class="delivery-title">✓ Checklist de Saída</div><div class="delivery-value">${money(d.price)}</div><div class="delivery-checks"><label><input type="checkbox" name="device_returned"> Aparelho conferido e devolvido</label><label><input type="checkbox" name="service_confirmed"> Serviço conferido com o cliente</label><label><input type="checkbox" name="warranty_explained"> Garantia e condições explicadas</label><label><input type="checkbox" name="payment_confirmed"> Pagamento confirmado</label></div>${f('payment','Forma de pagamento','select',['PIX','Dinheiro','Débito','Crédito','Transferência','Fiado/Crediário'])}${f('notes','Observação da entrega','textarea','',true)}<p class="muted">Confirmando, a OS vira ENTREGUE e o lançamento é sincronizado com o Financeiro.</p></div>`,async()=>{const m=$('#modal'),checks=[...m.querySelectorAll('.delivery-checks input')];if(checks.some(x=>!x.checked))return toast('Confirme todos os itens do checklist.','error');await api('/api/services',{method:'PUT',body:JSON.stringify({id,status:'entregue',notes:m.querySelector('[name=notes]').value})});closeModal();toast('Serviço entregue e financeiro atualizado');render()});setTimeout(()=>$('#modal').classList.add('delivery-modal'),30)};
window.statusServiceV500=async(id,status)=>{await api('/api/services',{method:'PUT',body:JSON.stringify({id,status})});toast('Status atualizado e link público sincronizado');render()};
window.deleteServiceV500=async id=>{if(!confirm('Excluir esta OS?'))return;await api('/api/services?id='+id,{method:'DELETE'});toast('OS excluída');render()};
window.deleteUnlockV500=async id=>{if(!confirm('Excluir este desbloqueio?'))return;await api('/api/unlocks?id='+id,{method:'DELETE'});toast('Desbloqueio excluído');render()};
window.copyOSLinkV500=async token=>{const u=location.origin+'/public/os/'+token;try{await navigator.clipboard.writeText(u)}catch{}toast('Link público da OS copiado')};
window.editServiceV500=async id=>{const d=(await api('/api/services?unit=TODOS')).find(x=>x.id===id);if(!d)return;formModal('Editar OS',`<div class="formgrid">${f('status','Status','select',['aberto','aguardando peça','em andamento','pronto','finalizado','entregue','cancelado'],d.status)}${f('technician','Técnico', 'text',d.technician||'')}${f('price','Valor','number',d.price||0)}${f('warranty','Garantia','text',d.warranty||'')}${f('cost_material','Custo peças','number',d.cost_material||0)}${f('cost_labor','Custo mão de obra','number',d.cost_labor||0)}${f('cost_extra','Outros custos','number',d.cost_extra||0)}${f('diagnosis','Diagnóstico','textarea',d.diagnosis||'',true)}${f('notes','Observações','textarea',d.notes||'',true)}</div>`,async()=>{const x=formValues($('#modalForm'));x.id=id;await api('/api/services',{method:'PUT',body:JSON.stringify(x)});closeModal();toast('OS atualizada');render()})};
window.editUnlockV500=async id=>{const d=(await api('/api/unlocks?unit=TODOS')).find(x=>x.id===id);if(!d)return;formModal('Editar desbloqueio',`<div class="formgrid">${f('status','Status','select',['aberto','em andamento','pronto','entregue','cancelado'],d.status)}${f('operator','Operador','text',d.operator||'')}${f('price','Valor','number',d.price||0)}${f('cost_material','Custo material','number',d.cost_material||0)}${f('cost_labor','Custo mão de obra','number',d.cost_labor||0)}${f('cost_extra','Outros custos','number',d.cost_extra||0)}${f('notes','Observações','textarea',d.notes||'',true)}</div>`,async()=>{const x=formValues($('#modalForm'));x.id=id;await api('/api/unlocks',{method:'PUT',body:JSON.stringify(x)});closeModal();toast('Desbloqueio atualizado');render();});};

// Unified OS V500: no visible database IDs.
pages.services=async()=>{const [s,u]=await Promise.all([list('services'),list('unlocks')]);const rows=[...s.map(x=>({...x,_type:'Técnica',_client:x.customer_name||'-',_device:[x.brand,x.model].filter(Boolean).join(' '),_value:x.price||0,_status:x.status})),...u.map(x=>({...x,_type:'Desbloqueio',_client:x.customer_name||'-',_device:[x.brand,x.model].filter(Boolean).join(' '),_value:x.price||0,_status:x.status}))].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));$('#content').innerHTML=analyticsHeader('Ordens de Serviço','Técnicas + Desbloqueios • ações completas • link público sincronizado',`<button class="btn" onclick="serviceForm()">＋ Nova OS Técnica</button><button class="btn dark" onclick="unlockForm()">🔓 Novo Desbloqueio</button>`)+`<div class="cards"><div class="metric"><div class="label">TOTAL OS</div><div class="value">${rows.length}</div></div><div class="metric"><div class="label">EM ANDAMENTO</div><div class="value yellow">${rows.filter(x=>/andamento|aguardando/i.test(x._status||'')).length}</div></div><div class="metric"><div class="label">PRONTOS</div><div class="value green">${rows.filter(x=>/pronto|finalizado/i.test(x._status||'')).length}</div></div><div class="metric"><div class="label">ENTREGUES</div><div class="value">${rows.filter(x=>x._status==='entregue').length}</div></div></div><div class="os-tabs"><button class="active" onclick="filterUnifiedOS('todos',this)">Todas <b>${rows.length}</b></button><button onclick="filterUnifiedOS('tecnica',this)">Técnicas <b>${s.length}</b></button><button onclick="filterUnifiedOS('unlock',this)">Desbloqueios <b>${u.length}</b></button></div><div id="unifiedOsTable">${table(rows,[['_type','Tipo',r=>r._type==='Desbloqueio'?'<span class="badge y">🔓 Desbloqueio</span>':'<span class="badge g">🔧 Técnica</span>'],['_client','Cliente'],['_device','Aparelho'],['_status','Status',r=>badge(r._status)],['_value','Valor',r=>money(r._value)]],r=>r._type==='Desbloqueio'?`<div class="row-actions"><button class="iconbtn" onclick="unlockDetails(${r.id})">👁️</button><button class="iconbtn" onclick="editUnlockV500(${r.id})">📝</button><button class="iconbtn" onclick="copyOSLinkV500('${r.public_token}')">🔗</button><button class="iconbtn danger" onclick="deleteUnlockV500(${r.id})">🗑️</button></div>`:`<div class="row-actions"><button class="iconbtn" onclick="serviceDetails(${r.id})">👁️</button><button class="iconbtn" onclick="editServiceV500(${r.id})">📝</button><button class="iconbtn" onclick="copyOSLinkV500('${r.public_token}')">🔗</button><button class="iconbtn" onclick="warrantyService(${r.id})">🛡️</button><button class="iconbtn" onclick="finalizeServiceV500(${r.id})">🔔</button><button class="iconbtn" onclick="deliverServiceV500(${r.id})">✓</button><button class="iconbtn danger" onclick="deleteServiceV500(${r.id})">🗑️</button></div><div class="status-actions">${['aberto','aguardando peça','em andamento','pronto','finalizado','entregue','cancelado'].map(st=>`<button class="mini ${st===r._status?'active':''}" onclick="statusServiceV500(${r.id},'${st}')">${st}</button>`).join('')}</div>`)}</div>`};

// Direct OS creation from abandoned devices, registered devices and purchases.
window.openServiceForDeviceV500=async function(source,id){let ctx;if(source==='forgotten'){ctx=(await api('/api/forgotten?unit=TODOS')).find(x=>x.id===id);if(!ctx)return;let cid=ctx.customer_id;if(!cid&&ctx.possible_owner){const found=await api('/api/customer-search?q='+encodeURIComponent(ctx.possible_owner));if(found[0])cid=found[0].id}if(!cid&&ctx.possible_owner){const cr=await api('/api/customers',{method:'POST',body:JSON.stringify({type:'PF',name:ctx.possible_owner,phone:ctx.phone,unit:ctx.unit})});cid=cr.id}serviceForm({unit:ctx.unit,customer_id:cid,customer_name:ctx.possible_owner,customer_phone:ctx.phone,brand:ctx.brand,model:ctx.model,imei:ctx.imei,description:'Conserto do aparelho abandonado / identificado na bancada'});}else{ctx=(await api('/api/devices?unit=TODOS')).find(x=>x.id===id);if(!ctx)return;serviceForm({unit:ctx.unit,customer_id:ctx.customer_id,customer_name:ctx.customer_name,customer_phone:ctx.customer_phone,brand:ctx.brand,model:ctx.model,imei:ctx.imei,serial:ctx.serial,device_id:ctx.id,description:'Conserto do aparelho cadastrado'});}};
window.openServiceForPurchaseV500=async function(id){const p=(await api('/api/purchases?unit=TODOS')).find(x=>x.id===id);if(!p)return;let deviceId=p.device_id;if(!deviceId){const r=await api('/api/devices',{method:'POST',body:JSON.stringify({unit:p.unit,customer_id:p.customer_id,brand:p.brand,model:p.model,imei:p.imei,status:'Em conserto',notes:'Aparelho originado da Compra e Venda'})});deviceId=r.id;await api('/api/purchases',{method:'PUT',body:JSON.stringify({id,device_id:deviceId})})}serviceForm({unit:p.unit,customer_id:p.customer_id,customer_name:p.customer_name,customer_phone:p.customer_phone,brand:p.brand,model:p.model,imei:p.imei,device_id:deviceId,description:'Conserto do aparelho da Compra e Venda'});};

// Device/purchase actions without exposing IDs.
pages.devices=async()=>{const [a,b]=await Promise.all([list('devices'),list('forgotten')]);const rows=[...a.map(x=>({...x,_source:'device',_condition:x.status||'Em bancada',_owner:x.customer_name||'-'})),...b.map(x=>({...x,_source:'forgotten',_condition:x.status||'Abandonado',_owner:x.possible_owner||'-'}))];$('#content').innerHTML=analyticsHeader('Aparelhos / Abandonados','Central única de bancada • conexão com clientes, OS e compra/venda',`<button class="btn" onclick="deviceForm()">＋ Novo aparelho</button><button class="btn dark" onclick="forgottenForm()">＋ Registrar abandono</button>`)+`<div class="cards"><div class="metric"><div class="label">TOTAL</div><div class="value">${rows.length}</div></div><div class="metric"><div class="label">EM BANCADA</div><div class="value">${rows.filter(x=>/bancada|conserto/i.test(x._condition)).length}</div></div><div class="metric"><div class="label">ABANDONADOS</div><div class="value red">${rows.filter(x=>/abandonado|aguardando dono/i.test(x._condition)).length}</div></div><div class="metric"><div class="label">SUCATA</div><div class="value red">${rows.filter(x=>/sucata/i.test(x._condition)).length}</div></div></div>`+table(rows,[['_source','Origem',r=>r._source==='forgotten'?'<span class="badge r">Abandonado</span>':'<span class="badge g">Cadastro</span>'],['brand','Marca'],['model','Modelo'],['imei','IMEI'],['_owner','Cliente / possível dono'],['_condition','Estado',r=>badge(r._condition)]],r=>`<div class="row-actions"><button class="iconbtn" onclick="${r._source==='forgotten'?`forgottenDetails(${r.id})`:`deviceDetailsV300(${r.id})`}">👁️</button><button class="iconbtn" onclick="${r._source==='forgotten'?`editForgotten(${r.id})`:`editDevice(${r.id})`}">📝</button><button class="iconbtn" onclick="openServiceForDeviceV500('${r._source}',${r.id})">🔧 OS</button><button class="iconbtn danger" onclick="deleteResource('${r._source==='forgotten'?'forgotten':'devices'}',${r.id})">🗑️</button></div>${deviceStateButtons(r._source,r.id,r._condition).replace('Liberado','Sucata')}`);};

pages.purchases=async()=>{const d=await list('purchases');const visible=d.filter(x=>x.status!=='vendido');$('#content').innerHTML=analyticsHeader('Compra e Venda','Compra → preparação → vitrine → PDV → vendido • conexão direta com OS',`<button class="btn" onclick="purchaseForm()">＋ Comprar aparelho</button><button class="btn dark" onclick="saleForm()">＋ Venda no PDV</button>`)+`<div class="cards"><div class="metric"><div class="label">EM PREPARAÇÃO</div><div class="value">${visible.filter(x=>x.status==='em preparação').length}</div></div><div class="metric"><div class="label">VITRINE / PDV</div><div class="value green">${visible.filter(x=>x.status==='vitrine').length}</div></div><div class="metric"><div class="label">RESERVADOS</div><div class="value yellow">${visible.filter(x=>x.status==='reservado').length}</div></div><div class="metric"><div class="label">VENDIDOS</div><div class="value">${d.filter(x=>x.status==='vendido').length}</div></div></div>`+table(visible,[['brand','Marca'],['model','Modelo / descrição'],['imei','IMEI'],['total_cost','Custo',r=>money(r.total_cost)],['suggested_price','Venda',r=>money(r.suggested_price)],['status','Status',r=>badge(r.status)]],r=>`<div class="row-actions"><button class="iconbtn" onclick="editPurchase(${r.id})">📝</button><button class="iconbtn" onclick="openServiceForPurchaseV500(${r.id})">🔧 OS</button><button class="iconbtn" onclick="sendToVitrine(${r.id})">🟡 Vitrine</button><button class="iconbtn danger" onclick="deleteResource('purchases',${r.id})">🗑️</button></div>`) };

// Quotes: real item editing + automatic totals + approved -> OS.
window.quoteItemsEditorV500=function(items){return `<div class="field full"><label>Itens do orçamento</label><div id="quoteItemsV500">${(items||[]).map(x=>`<div class="item-row"><input class="input qi-desc-v500" value="${esc(x.description||x.name||'')}" placeholder="Serviço / peça"><input class="input qi-qty-v500" type="number" min="1" value="${x.qty||1}"><input class="input qi-total-v500" type="number" step="0.01" min="0" value="${x.total||x.price||0}"><button type="button" class="iconbtn danger" onclick="this.parentElement.remove()">✕</button></div>`).join('')}</div><button type="button" class="btn ghost" onclick="addQuoteItemV500()">＋ Adicionar item</button></div>`};
window.addQuoteItemV500=function(){const b=$('#quoteItemsV500');if(!b)return;const d=document.createElement('div');d.className='item-row';d.innerHTML='<input class="input qi-desc-v500" placeholder="Serviço / peça"><input class="input qi-qty-v500" type="number" min="1" value="1"><input class="input qi-total-v500" type="number" step="0.01" min="0" value="0"><button type="button" class="iconbtn danger" onclick="this.parentElement.remove()">✕</button>';b.appendChild(d)};
window.editQuoteV500=async function(id){const q=(await api('/api/quotes?unit=TODOS')).find(x=>x.id===id);if(!q)return;let items=[];try{items=JSON.parse(q.items||'[]')}catch{};formModal('Editar orçamento',`<div class="formgrid">${f('status','Status','select',['aberto','enviado','aprovado','recusado','expirado'],q.status)}${f('valid_until','Validade','date',q.valid_until||'')}${f('warranty_days','Dias de garantia','number',q.warranty_days||0)}${f('travel_enabled','Deslocamento','select',['0','1'],q.travel_enabled?'1':'0')}${f('travel_fee','Taxa de deslocamento','number',q.travel_fee||0)}${quoteItemsEditorV500(items)}${f('conditions','Condições','textarea',q.conditions||'',true)}${f('observations','Observações','textarea',q.observations||'',true)}</div>`,async()=>{const m=$('#modal'),x=formValues(m.querySelector('#modalForm'));x.id=id;x.items=$$('#quoteItemsV500 .item-row').map(r=>({description:r.querySelector('.qi-desc-v500').value,qty:Number(r.querySelector('.qi-qty-v500').value||1),total:Number(r.querySelector('.qi-total-v500').value||0)})).filter(x=>x.description);x.subtotal=x.items.reduce((a,i)=>a+i.total,0);x.total=x.subtotal+(x.travel_enabled==='1'?Number(x.travel_fee||0):0);await api('/api/quotes',{method:'PUT',body:JSON.stringify(x)});closeModal();toast('Orçamento e itens atualizados');render()})};
window.generateOSFromQuoteV500=async function(id){const q=(await api('/api/quotes?unit=TODOS')).find(x=>x.id===id);if(!q)return;if(q.status!=='aprovado')return toast('Somente orçamentos aprovados podem gerar OS.','error');let items=[];try{items=JSON.parse(q.items||'[]')}catch{};serviceForm({unit:q.unit,customer_id:q.customer_id,device_id:q.device_id,description:items.map(x=>`${x.description} (${x.qty||1}x)`).join(', '),details:{quote_id:id,quote_number:q.number,items}})};
const _quotesPageV500=pages.quotes;pages.quotes=async()=>{await _quotesPageV500();try{const q=await api('/api/quotes?unit='+encodeURIComponent(UNIT));const box=$('#content');if(box)box.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:16px"><div class="panel-head"><h2>Ações avançadas dos orçamentos</h2><span class="badge y">Editar • Excluir • Gerar OS</span></div>${table(q,[['number','Orçamento'],['customer_name','Cliente'],['status','Status',r=>badge(r.status)],['total','Total',r=>money(r.total)],['valid_until','Validade']],r=>`<div class="row-actions"><button class="iconbtn" onclick="editQuoteV500(${r.id})">📝</button><button class="iconbtn" title="Copiar link" onclick="copyQuoteLink('${r.public_token}')">🔗</button><button class="iconbtn" title="WhatsApp" onclick="whatsappQuote(${r.id})">💬</button>${r.status==='aprovado'?`<button class="iconbtn" title="Gerar OS" onclick="generateOSFromQuoteV500(${r.id})">🔧 OS</button>`:''}<button class="iconbtn danger" onclick="deleteResource('quotes',${r.id})">🗑️</button></div>`)}</section>`)}catch{}};

// Fiado keeps V300's installment calculator and adds a real CRM & Cobrança view + MDM tab.
window.fiadoCRMv500=async function(){const d=await api('/api/fiado?unit='+encodeURIComponent(UNIT));const open=d.filter(x=>x.balance>0), overdue=open.filter(x=>x.status==='atrasado');$('#content').innerHTML=analyticsHeader('CRM & Cobrança','Clientes devedores, parcelas, vencimentos e ações de cobrança',`<button class="btn" onclick="fiadoForm()">＋ Nova promissória</button>`)+`<div class="cards"><div class="metric"><div class="label">CLIENTES EM ABERTO</div><div class="value">${new Set(open.map(x=>x.customer_id)).size}</div></div><div class="metric"><div class="label">A RECEBER</div><div class="value yellow">${money(open.reduce((a,x)=>a+Number(x.balance||0),0))}</div></div><div class="metric"><div class="label">VENCIDO</div><div class="value red">${money(overdue.reduce((a,x)=>a+Number(x.balance||0),0))}</div></div><div class="metric"><div class="label">PROMISSÓRIAS</div><div class="value">${d.length}</div></div></div>${table(d,[['customer_name','Cliente'],['description','Serviço / compra'],['installments','Parcelas',r=>`${r.installments||1}x`],['installment_value','Valor parcela',r=>money(r.installment_value)],['balance','Saldo',r=>money(r.balance)],['due_date','Próximo vencimento'],['status','Status',r=>badge(r.status)]],r=>`<div class="row-actions"><button class="iconbtn" onclick="fiadoDetails(${r.id})">👁️</button><button class="iconbtn" onclick="receiveFiado(${r.id},${r.balance})">💰</button><button class="iconbtn" onclick="fiadoWhats(${r.id})">💬</button></div>`)}`};
window.mdmQR=async function(id){try{const app=await api('/api/mdm/qr?id='+id+'&mode=app');let prov=null;try{prov=await api('/api/mdm/qr?id='+id+'&mode=provisioning')}catch{}formModal('QR • Crediário MDM Android',`<div class="mdm-qr"><div class="grid2"><section class="panel"><h3>QR do aplicativo</h3><img src="${app.data_url}" alt="QR aplicativo"><code>${esc(app.payload)}</code><p class="muted">Com o aplicativo KV CELL instalado, o QR vincula o token ao aparelho.</p></section><section class="panel"><h3>QR de provisionamento</h3>${prov?`<img src="${prov.data_url}" alt="QR provisionamento"><code>${esc(prov.payload)}</code>`:'<p class="muted">Disponível quando MDM_AGENT_APK_URL estiver configurado no servidor.</p>'}</section></div></div>`,async()=>closeModal())}catch(e){toast(e.message,'error')}};
window.mdmAction=async function(id,action){const labels={lock:'bloquear',unlock:'liberar',pause:'pausar'};if(!confirm(`Confirmar ${labels[action]||action} este aparelho?`))return;try{await api('/api/mdm/action',{method:'POST',body:JSON.stringify({id,action})});toast('Política MDM atualizada');await mdmInlineV500()}catch(e){toast(e.message,'error')}};
window.mdmDetails=async function(id){const d=(await api('/api/mdm?unit=TODOS')).find(x=>x.id===Number(id));if(!d)return;const balance=Math.max(0,Number(d.installment_total||0)-Number(d.installment_paid||0));const remaining=Math.max(0,Number(d.installment_count||0)-Number(d.paid_installments||0));formModal('Detalhes do Crediário MDM',`<div class="cards"><div class="metric"><div class="label">SALDO</div><div class="value yellow">${money(balance)}</div></div><div class="metric"><div class="label">PARCELAS RESTANTES</div><div class="value">${remaining}</div></div><div class="metric"><div class="label">STATUS</div><div class="value">${esc(d.status||'—')}</div></div><div class="metric"><div class="label">POLÍTICA</div><div class="value">${esc(d.policy_state||'—')}</div></div></div><div class="panel"><div class="kpi"><span>Cliente</span><b>${esc(d.customer_name||'—')}</b></div><div class="kpi"><span>Aparelho</span><b>${esc(d.device_name||`${d.brand||''} ${d.model||''}`)}</b></div><div class="kpi"><span>IMEI</span><b>${esc(d.imei||'—')}</b></div><div class="kpi"><span>Vencimento</span><b>${esc(d.next_due||'—')}</b></div><div class="kpi"><span>Último heartbeat</span><b>${esc(d.last_seen||'—')}</b></div></div>`,async()=>closeModal())};
window.mdmInlineV500=async function(){const d=await api('/api/mdm?unit='+encodeURIComponent(UNIT));const today=new Date().toISOString().slice(0,10);$('#content').innerHTML=analyticsHeader('Crediário / MDM Android','Aparelhos vendidos no crediário • QR • provisionamento legítimo • parcelas e política remota',`<button class="btn" onclick="mdmForm()">＋ Novo crediário MDM</button>`)+`<div class="cards"><div class="metric"><div class="label">APARELHOS</div><div class="value">${d.length}</div></div><div class="metric"><div class="label">ONLINE</div><div class="value green">${d.filter(x=>x.status==='online').length}</div></div><div class="metric"><div class="label">BLOQUEADOS</div><div class="value red">${d.filter(x=>x.policy_state==='bloqueado').length}</div></div><div class="metric"><div class="label">VENCIDOS</div><div class="value yellow">${d.filter(x=>x.next_due&&x.next_due<today&&x.policy_state!=='quitado').length}</div></div></div>${table(d,[['device_name','Aparelho'],['customer_name','Cliente'],['imei','IMEI'],['installment_total','Financiado',r=>money(r.installment_total)],['installment_paid','Pago',r=>money(r.installment_paid)],['next_due','Vencimento'],['policy_state','Política',r=>badge(r.policy_state)]],r=>`<div class="row-actions"><button class="iconbtn" onclick="mdmQR(${r.id})">▦ QR</button><button class="iconbtn" onclick="mdmDetails(${r.id})">👁️</button><button class="iconbtn" onclick="mdmAction(${r.id},'lock')">🔒</button><button class="iconbtn" onclick="mdmAction(${r.id},'unlock')">🔓</button><button class="iconbtn danger" onclick="deleteResource('mdm',${r.id})">🗑️</button></div>`)}`};
const _fiadoBaseV500=pages.fiado;pages.fiado=async()=>{await _fiadoBaseV500();const c=$('#content');if(!c)return;const tabs=c.querySelector('.subtabs');if(tabs){tabs.innerHTML='<button class="active" data-ft="promissorias">$ Promissórias</button><button data-ft="crm">♧ CRM & Cobrança</button><button data-ft="mdm">📱 Crediário / MDM</button>';tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{tabs.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.ft==='crm')fiadoCRMv500();else if(b.dataset.ft==='mdm')mdmInlineV500();else _fiadoBaseV500()})}};

