window.mdmFromFiado=async function(id){const d=(await api('/api/fiado?unit=TODOS')).find(x=>x.id===id);if(!d)return;const seed={unit:d.unit,customer_id:d.customer_id,fiado_id:d.id,installment_total:d.total,installment_paid:Number(d.total||0)-Number(d.balance||0),installment_count:d.installments||1,installment_value:d.installment_value||0,next_due:d.due_date,device_name:d.description||'Aparelho do crediário'};formModal('Vincular aparelho ao Crediário / MDM',`<div class="formgrid">${f('unit','Unidade','select',['LAGOS','MAGÉ'],seed.unit)}${customerPickerV500('customer_id','Cliente')}${f('fiado_id','Fiado vinculado','hidden',seed.fiado_id)}${f('brand','Marca *')}${f('model','Modelo *')}${f('imei','IMEI')}${f('serial','Número de série')}${f('android_version','Android')}${f('device_name','Nome do aparelho', 'text',seed.device_name)}${f('installment_total','Valor financiado','number',seed.installment_total)}${f('installment_paid','Valor já pago','number',seed.installment_paid)}${f('installment_count','Parcelas','number',seed.installment_count)}${f('installment_value','Valor da parcela','number',seed.installment_value)}${f('paid_installments','Parcelas pagas','number',Math.max(0,(seed.installment_count||1)-Math.ceil(Number(seed.balance||0)/Math.max(1,Number(seed.installment_value||1)))))}${f('next_due','Próximo vencimento','date',seed.next_due||'')}${f('payment_url','Link de pagamento','url','')}${f('pix_copy_paste','PIX copia e cola','textarea','',true)}</div>`,async()=>{const m=$('#modal'),x=formValues(m.querySelector('#modalForm'));if(!x.customer_id)return toast('Selecione o cliente.','error');let ok=false,last;for(let attempt=1;attempt<=3&&!ok;attempt++){try{await api('/api/mdm/create',{method:'POST',body:JSON.stringify(x)});ok=true}catch(err){last=err;if(attempt<3)await new Promise(res=>setTimeout(res,900*attempt))}}if(!ok)throw last;closeModal();toast('Aparelho vinculado ao fiado e QR criado');await mdmInlineV500()});setTimeout(()=>{wirePickersV500();preselectCustomerV500(seed.customer_id)},50)};

