/* ================================================================
   V502 — ADB & ANTIVÍRUS / CENTRAL DE BANCADA DARK
   Ponte local real: http://127.0.0.1:17321
   Mantém as funções antigas intactas e substitui apenas a interface ADB.
================================================================ */
window.__kvAdbBridge = localStorage.getItem('kv_adb_bridge') || 'http://127.0.0.1:17321';
window.__kvAdbSerial = localStorage.getItem('kv_adb_serial') || '';
window.__kvAdbDevice = null;
window.__kvAdbTab = 'hub';
window.__kvAdbOutput = '';
window.__kvAdbScan = null;

async function kvBridge(path, opts={}){
  const base=(window.__kvAdbBridge||'').replace(/\/$/,'');
  if(!base) throw new Error('Ponte ADB não configurada.');
  const method=String(opts.method||'GET').toUpperCase();
  const headers={...(opts.headers||{})};
  if(method!=='GET' && method!=='HEAD' && !headers['Content-Type']) headers['Content-Type']='application/json';
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(),Number(opts.timeout||1800));
  try{
    const r=await fetch(base+path,{...opts,headers,signal:controller.signal});
    let d;
    try{d=await r.json()}catch{throw new Error('A ponte ADB respondeu com um formato inválido.')}
    if(!r.ok || d.error) throw new Error(d.error||('Erro HTTP '+r.status));
    return d;
  }catch(e){
    if(e?.name==='AbortError') throw new Error('Ponte ADB não respondeu em tempo hábil.');
    throw e;
  }finally{clearTimeout(timer)}
}
function kvAdbBadge(ok,text){return `<span class="adb502-badge ${ok?'ok':'warn'}"><i></i>${esc(text)}</span>`}
function kvAdbDevice(){return window.__kvAdbDevice||{};}
function kvAdbSerial(){return window.__kvAdbSerial||'';}
function kvAdbInfoValue(v){return esc(v===undefined||v===null||v===''?'—':v)}
function kvAdbMetric(label,value,cls=''){return `<div class="adb502-metric"><span>${esc(label)}</span><b class="${cls}">${kvAdbInfoValue(value)}</b></div>`}
function kvAdbSection(title,sub,body,actions=''){return `<section class="adb502-panel"><div class="adb502-panel-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div><div class="adb502-actions">${actions}</div></div>${body}</section>`}

async function kvAdbHealth(){
  try{const d=await kvBridge('/health');return d.ok&&d.adb_found}catch{return false}
}
async function kvAdbDevices(){
  const d=await kvBridge('/devices');
  const online=(d.devices||[]).filter(x=>x.state==='device');
  if(!online.length){window.__kvAdbDevice=null;window.__kvAdbSerial='';localStorage.removeItem('kv_adb_serial');return d.devices||[]}
  let current=online.find(x=>x.serial===window.__kvAdbSerial);
  if(!current){current=online[0];window.__kvAdbSerial=current.serial;localStorage.setItem('kv_adb_serial',current.serial)}
  return d.devices||[];
}
async function kvAdbLoadInfo(){
  const d=await kvBridge('/device?serial='+encodeURIComponent(kvAdbSerial()));
  window.__kvAdbDevice=d.device; return d.device;
}

